#!/usr/bin/env bash
# Question 1: Worker after a configuration change. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

[[ "$CKA_NODE" == "${Q1_NODE}" ]] || exit 0

case "${Q1_FAULT}" in
  kubelet-kubeconfig-server)
    sed -i -E 's#^([[:space:]]*server: https://[^[:space:]]+):6443$#\1:6444#' /etc/kubernetes/kubelet.conf
    grep -qE -- 'server: https://[^[:space:]]+:6444$' /etc/kubernetes/kubelet.conf || { echo "could not modify /etc/kubernetes/kubelet.conf" >&2; exit 1; }
    systemctl restart kubelet || true
    ;;
esac
